        &tools,
        plan.calls(),
        &interceptors,
        &tool_ctx,
        parallel_tool_call_limit,
        &run_span,
    )
    .await;
    for ev in denied {
        yield ev;
    }
    let mut results = Vec::with_capacity(outcomes.len());
    for o in outcomes {
        let item = crate::Item::ToolResult {
            call_id: o.call_id,
            content: o.result.unwrap_or_else(|e| {
